const $=id=>document.getElementById(id);
const lessons=[['Домашний ряд','фыва олдж'],['Указательные пальцы','апро'],['Средние пальцы','ву ке'],['Безымянные пальцы','ыц шл'],['Мизинцы','фйя жзхъэ'],['Нижний ряд','ячсмитьбю'],['Все буквы','фывапролджэ йцукенгшщзхъ ячсмитьбю']];
const groups=[['фйя','левый мизинец'],['ыцы','левый безымянный'],['вус','левый средний'],['акепм','левый указательный'],['онгрт','правый указательный'],['лши','правый средний'],['дщб','правый безымянный'],['жэзхъюё','правый мизинец']];
let saved={};try{saved=JSON.parse(localStorage.getItem('ten-fingers')||'{}')}catch{}let lesson=0,target='',pos=0,total=0,errors=0,start=0,finished=false,wrong=false;
function storeProgress(){try{localStorage.setItem('ten-fingers',JSON.stringify(saved))}catch{}}
function menu(){$('lessons').innerHTML=lessons.map((l,i)=>`<button data-lesson="${i}" class="${i===lesson?'selected':''}">${saved[i]?'✓ ':''}${i+1}. ${l[0]}</button>`).join('');$('progress').textContent=`Пройдено ${Object.keys(saved).length} из ${lessons.length} уроков`;document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{lesson=+b.dataset.lesson;$('mode').value='lesson';reset()})}
function makeTarget(){let mode=$('mode').value;if(mode==='words')return 'мама папа дом вода рука окно работа слово книга город школа время';if(mode==='text')return 'печатай спокойно и внимательно. возвращай пальцы на исходную позицию. каждый день практика помогает двигаться уверенно.';let chars=lessons[lesson][1].replaceAll(' ','');let words=[];for(let i=0;i<12;i++){let word='';for(let j=0;j<4;j++)word+=chars[Math.floor(Math.random()*chars.length)];words.push(word)}return words.join(' ')}
function render(){const t=$('text');t.replaceChildren();for(let i=0;i<target.length;i++){let s=document.createElement('span');s.textContent=target[i];s.className=i<pos?'done':i===pos?'current'+(wrong?' wrong':''):'';t.append(s)}$('position').textContent=`${pos} / ${target.length}`;$('accuracy').textContent=(total?Math.round((total-errors)/total*100):100)+'%';$('speed').textContent=start?Math.round(pos/Math.max((Date.now()-start)/60000,1/60)):0;document.querySelectorAll('.key').forEach(k=>k.classList.toggle('target',k.dataset.char===target[pos]));let ch=target[pos];let finger=ch===' '?'большой палец':(groups.find(g=>g[0].includes(ch))||[])[1];$('hint').textContent=finished?'Упражнение завершено.':`Следующая клавиша: ${ch===' '?'пробел':ch||''}${finger?' · '+finger:''}${wrong?' · исправь ошибку, набрав нужный символ':''}`}
function reset(){pos=total=errors=start=0;finished=wrong=false;target=makeTarget();$('title').textContent=$('mode').value==='lesson'?`${lesson+1}. ${lessons[lesson][0]}`:$('mode').selectedOptions[0].textContent;$('input').disabled=false;$('input').value='';$('result').classList.add('hidden');$('next').disabled=lesson===lessons.length-1;menu();render()}
function type(text){if(finished)return;for(const ch of text){if(finished)break;if(!start)start=Date.now();total++;if(ch===target[pos]){pos++;wrong=false}else{errors++;wrong=true}if(pos===target.length){finished=true;let accuracy=Math.round((total-errors)/total*100);if($('mode').value==='lesson'&&accuracy>=95){saved[lesson]=true;storeProgress();menu()}$('input').disabled=true;$('result').textContent=`Готово! Точность ${accuracy}%, скорость ${Math.round(pos/Math.max((Date.now()-start)/60000,1/60))} зн/мин. ${accuracy>=95?'Отлично — можно двигаться дальше.':'Повтори упражнение и постарайся достичь точности 95%.'}`;$('result').classList.remove('hidden')}}render()}
$('input').addEventListener('beforeinput',e=>{if(e.inputType.startsWith('insert')){e.preventDefault();if(e.inputType==='insertFromPaste')return;if(e.data)type(e.data)}else e.preventDefault()});$('input').addEventListener('paste',e=>e.preventDefault());$('input').addEventListener('input',e=>{if(e.target.value){type(e.target.value);e.target.value=''}});
for(const row of ['йцукенгшщзхъ','фывапролджэ','ячсмитьбю',' ']){let r=document.createElement('div');r.className='row';for(const char of row){let k=document.createElement('div');k.className='key'+('ао'.includes(char)?' home':'');k.dataset.char=char;k.textContent=char===' '?'пробел':char;if(char===' ')k.style.width='240px';r.append(k)}$('keys').append(r)}
$('restart').onclick=()=>{reset();$('input').focus()};$('next').onclick=()=>{if(lesson<lessons.length-1){lesson++;$('mode').value='lesson';reset();$('input').focus()}};$('mode').onchange=reset;setInterval(()=>{if(start&&!finished)render()},1000);reset();
